// Validar que el evento sea un deal.updated con stage_id = 62
// y que el deal pertenezca al pipeline 6 (Bayteca)

const body = $input.first().json.body || $input.first().json;

// Pipedrive envía el evento con 'current' y 'previous' data
const current = body.current || body;
const meta = body.meta || {};

const stageId = current.stage_id || current.current_stage_id;
const pipelineId = current.pipeline_id;

if (stageId !== 62) {
  return [{ json: { skip: true, reason: `stage_id=${stageId}, expected 62` } }];
}

if (pipelineId && pipelineId !== 6) {
  return [{ json: { skip: true, reason: `pipeline_id=${pipelineId}, expected 6` } }];
}

const dealId = current.id || body.id;
if (!dealId) {
  return [{ json: { skip: true, reason: 'No deal ID found' } }];
}

return [{ json: { dealId, stageId, pipelineId, ok: true } }];

// Detectar si alguno de Bank 1–5 es Kutxabank
// Kutxabank option IDs: 2633 (B1), 2651 (B2), 2669 (B3), 2687 (B4), 2705 (B5)

const deal = $input.first().json;

const KUTXA_OPTION_IDS = [2633, 2651, 2669, 2687, 2705];

const BANK_FIELD_IDS = [
  'af536dbfe7d00fd441ae9bd4b144c25bc1d4c725', // Bank 1
  '8e4b44a3f3973d1f524f8cd0ec6f6babe9e96965', // Bank 2
  'ed0a30972778ac2c3d29cab53e27a89f5b52a1b2', // Bank 3
  '9049591570e78d3274a72cfb7a28076789ce0676', // Bank 4
  '36ff3525fb8a73637e069099967b2afe164e408a', // Bank 5
];

const BANK_ID_FIELD_IDS = [
  '04d666f12e4d27a3867daa5d7d6b777d76d24eb9', // Bank 1 ID
  '75d8963d89d47daf37349722c531677263173484', // Bank 2 ID
  '874add027adde7fa7690874e3bac581489387651', // Bank 3 ID
  '467feaa56488620159ef39890e6d8f96489bdbac', // Bank 4 ID
  'b3dfef96dce320a1cfa4605056757f7e79731676', // Bank 5 ID
];

const BANK_LINK_FIELD_IDS = [
  'fc8312a76b8fe194ba55b60f3e09ac7e7800a5bd', // Bank 1 link
  'd78cdb37e370d21facdea787f4bd7a22520ac62d', // Bank 2 link
  'b3b1fd8fba90a455d01fb4aa4805569d4b60070a', // Bank 3 link
  '9a4d771432722d30f6e4abe8f0cee6a542793475', // Bank 4 link
  '963244c4d383295066674c693d813b4abb27ae11', // Bank 5 link
];

function parseBankDealId(raw) {
  if (raw == null) return null;
  const str = String(raw).trim();
  const n = parseInt(str, 10);
  if (!isNaN(n) && n > 0) return n;
  const m = str.match(/\/deal\/(\d+)/);
  if (m) { const id = parseInt(m[1], 10); if (!isNaN(id) && id > 0) return id; }
  return null;
}

let kutxaSlot = -1;
for (let i = 0; i < BANK_FIELD_IDS.length; i++) {
  const rawVal = deal[BANK_FIELD_IDS[i]];
  const numVal = rawVal != null ? parseInt(String(rawVal), 10) : NaN;
  if (!isNaN(numVal) && KUTXA_OPTION_IDS[i] === numVal) {
    kutxaSlot = i;
    break;
  }
}

if (kutxaSlot === -1) {
  return [{ json: { isKutxa: false, reason: 'Kutxabank not in Bank 1–5' } }];
}

const bankDealId =
  parseBankDealId(deal[BANK_ID_FIELD_IDS[kutxaSlot]]) ??
  parseBankDealId(deal[BANK_LINK_FIELD_IDS[kutxaSlot]]);

// Extract Google Drive folder ID from URL
const driveUrl = deal['c2ea08d72de437ee4957ff3807c48cebe7a1aa3e'] || '';
const folderMatch = driveUrl.match(/\/folders\/([a-zA-Z0-9_-]+)/);
const folderId = folderMatch ? folderMatch[1].split('?')[0] : null;

const dni = deal['60228dc43313b931378ec9bb3f21f7ad7f5a144c'] || '';
const plan = deal['b5d36c005e38a4cd72d831be655996a3d6b34dc1'] || '';
const nombreCliente = deal.person_name || '';
const secondTitular = deal['209a0da7966a29bf05e96b6a124536222e0318dd'] || '';

return [{
  json: {
    isKutxa: true,
    dealId: deal.id,
    bankDealId,
    folderId,
    driveUrl,
    dni,
    plan,
    nombreCliente,
    hasSecondTitular: !!secondTitular,
    kutxaSlot
  }
}];

// Filtrar los archivos encontrados para C003–C008 y D003–D008
// y registrar los que faltan

const info = $('Detectar Kutxabank').item.json;
const allFiles = $input.all();

const DOC_CODES_1T = ['C003', 'C004', 'C005', 'C006', 'C007', 'C008'];
const DOC_CODES_2T = ['D003', 'D004', 'D005', 'D006', 'D007', 'D008'];

const neededCodes = [...DOC_CODES_1T];
if (info.hasSecondTitular) neededCodes.push(...DOC_CODES_2T);

// Map filename → file item
const foundFiles = {}; // code → { id, name }
const missingDocs = [];

for (const item of allFiles) {
  const file = item.json;
  const fileName = file.name || '';
  for (const code of neededCodes) {
    if (fileName.includes(code) && !foundFiles[code]) {
      foundFiles[code] = { id: file.id, name: fileName };
    }
  }
}

for (const code of neededCodes) {
  if (!foundFiles[code]) missingDocs.push(code);
}

const filesToDownload = Object.values(foundFiles);

if (filesToDownload.length === 0) {
  // Nothing to download — still create Supabase record with all docs missing
  return [{
    json: {
      ...info,
      filesToDownload: [],
      missingDocs,
      zipFilename: `Kutxabank_${info.bankDealId}_${info.nombreCliente.replace(/\s+/g, '_')}_${info.dni}.zip`,
    }
  }];
}

// Return one item per file to download, carrying the context
return filesToDownload.map((f, idx) => ({
  json: {
    ...info,
    fileId: f.id,
    fileName: f.name,
    isLastFile: idx === filesToDownload.length - 1,
    totalFiles: filesToDownload.length,
    missingDocs,
    zipFilename: `Kutxabank_${info.bankDealId}_${info.nombreCliente.replace(/\s+/g, '_')}_${info.dni}.zip`,
  }
}));

// Crear ZIP (sin encriptación) con los documentos del cliente
// ZipCrypto fue eliminado — causaba PDFs corruptos. El link en Drive/Pipedrive ya es privado.

const allItems = $input.first().json.allItems || [];
const ctx = allItems[0]?.json || {};
const zipFilename = ctx.zipFilename || `Kutxabank_${ctx.bankDealId || 'unknown'}.zip`;
const missingDocs = ctx.missingDocs || [];

// ── ZIP helpers ────────────────────────────────────────────────────────────
function u16(a, o, v) { a[o] = v & 0xFF; a[o+1] = (v >> 8) & 0xFF; }
function u32(a, o, v) { v = v >>> 0; a[o]=v&0xFF; a[o+1]=(v>>8)&0xFF; a[o+2]=(v>>16)&0xFF; a[o+3]=(v>>24)&0xFF; }

const CRC_TABLE = new Uint32Array(256);
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  CRC_TABLE[n] = c;
}
function crc32(data) {
  let c = 0xFFFFFFFF;
  for (const b of data) c = (CRC_TABLE[(c ^ b) & 0xFF] ^ (c >>> 8)) >>> 0;
  return (c ^ 0xFFFFFFFF) >>> 0;
}

// ── Collect files from aggregated items ────────────────────────────────────
const files = [];
for (const item of allItems) {
  const bin = item.binary || {};
  for (const [, bdata] of Object.entries(bin)) {
    if (bdata && bdata.data) {
      const buf = Buffer.from(bdata.data, 'base64');
      files.push({
        name: bdata.fileName || 'documento.pdf',
        data: new Uint8Array(buf)
      });
    }
  }
}

if (files.length === 0) {
  return [{ json: { ...ctx, zipCreated: false, missingDocs, zipFilename, fileCount: 0 } }];
}

// ── Build unencrypted stored ZIP ───────────────────────────────────────────
const now = new Date();
const dosTime = (now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1);
const dosDate = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();

const parts = [];
const cds = [];
let off = 0;

for (const { name, data } of files) {
  const nameB = new TextEncoder().encode(name);
  const crc = crc32(data);

  // Local File Header
  const lh = new Uint8Array(30 + nameB.length);
  u32(lh, 0, 0x04034B50); u16(lh, 4, 20);
  u16(lh, 6, 0);           // GP flag = 0 (no encryption)
  u16(lh, 8, 0);           // compression = stored
  u16(lh, 10, dosTime); u16(lh, 12, dosDate);
  u32(lh, 14, crc);
  u32(lh, 18, data.length); // compressed = uncompressed
  u32(lh, 22, data.length);
  u16(lh, 26, nameB.length); u16(lh, 28, 0);
  lh.set(nameB, 30);
  parts.push(lh, data);

  // Central Directory Header
  const cd = new Uint8Array(46 + nameB.length);
  u32(cd, 0, 0x02014B50); u16(cd, 4, 20); u16(cd, 6, 20);
  u16(cd, 8, 0); u16(cd, 10, 0);
  u16(cd, 12, dosTime); u16(cd, 14, dosDate);
  u32(cd, 16, crc);
  u32(cd, 20, data.length); u32(cd, 24, data.length);
  u16(cd, 28, nameB.length); u16(cd, 30, 0); u16(cd, 32, 0);
  u16(cd, 34, 0); u16(cd, 36, 0); u32(cd, 38, 0x20);
  u32(cd, 42, off);
  cd.set(nameB, 46);
  cds.push(cd);

  off += 30 + nameB.length + data.length;
}

const cdOff = off;
let cdSz = 0;
for (const cd of cds) { parts.push(cd); cdSz += cd.length; }

const eocdr = new Uint8Array(22);
u32(eocdr, 0, 0x06054B50); u16(eocdr, 4, 0); u16(eocdr, 6, 0);
u16(eocdr, 8, files.length); u16(eocdr, 10, files.length);
u32(eocdr, 12, cdSz); u32(eocdr, 16, cdOff); u16(eocdr, 20, 0);
parts.push(eocdr);

const total = parts.reduce((s, p) => s + p.length, 0);
const zip = new Uint8Array(total);
let pos = 0;
for (const p of parts) { zip.set(p, pos); pos += p.length; }

return [{
  json: { ...ctx, zipCreated: true, missingDocs, zipFilename, fileCount: files.length },
  binary: {
    data: {
      data: Buffer.from(zip).toString('base64'),
      mimeType: 'application/zip',
      fileName: zipFilename
    }
  }
}];

// Construir el link de Drive y preparar datos para Supabase y Rastreator
const zipInfo = $('Crear ZIP encriptado').item.json;
const uploadResult = $input.first().json;

const zipFileId = uploadResult.id || uploadResult.fileId || '';
const zipDriveLink = zipFileId
  ? `https://drive.google.com/file/d/${zipFileId}/view`
  : '';

return [{
  json: {
    ...zipInfo,
    zipFileId,
    zipDriveLink,
  }
}];

